import sys

data = sys.stdin.read().split()
n = int(data[0])
p = [int(x) for x in data[1:1 + n]]
if n <= 700:
    best = 0
    for k in range(n):
        s = 0
        w = 0
        for i in range(n):
            if (i + k) % n == p[i]:
                s += 1
            if (k - i) % n == p[i]:
                w += 1
        if s > best:
            best = s
        if w > best:
            best = w
    print(best)
else:
    best = 1
    for arr in (sorted((p[i] - i) % n for i in range(n)), sorted((p[i] + i) % n for i in range(n))):
        run = 1
        for j in range(1, n):
            run = run + 1 if arr[j] == arr[j - 1] else 1
            if run > best:
                best = run
    print(best)
